ruleContent.content:
@js:
var marker = 'window.__INITIAL_STATE__';
var markerStart = result.indexOf(marker);
if (markerStart < 0) { return ''; }
var jsonStart = result.indexOf('{', markerStart + marker.length);
if (jsonStart < 0) { return ''; }
var depth = 0;
var inString = false;
var escaped = false;
var jsonEnd = -1;
for (var i = jsonStart; i < result.length; i++) {
  var ch = result.charAt(i);
  if (inString) {
    if (escaped) { escaped = false; }
    else if (ch == String.fromCharCode(92)) { escaped = true; }
    else if (ch == String.fromCharCode(34)) { inString = false; }
  } else if (ch == String.fromCharCode(34)) { inString = true; }
  else if (ch == '{') { depth++; }
  else if (ch == '}') { depth--; if (depth == 0) { jsonEnd = i + 1; break; } }
}
if (jsonEnd < 0) { return ''; }
var state = JSON.parse(result.substring(jsonStart, jsonEnd));
return state.reader.chapterData.content || '';

